def maximumScore(grid: List[List[int]]) -> int:
    n = len(grid)
    cp = [[0] * (n + 1) for _ in range(n)]
    for j in range(n):
        col = cp[j]
        for i in range(n):
            col[i + 1] = col[i] + grid[i][j]
    NEG = float('-inf')
    # dp[prev][cur]: best score of columns before the current one, where prev/cur are black heights
    dp = [[NEG] * (n + 1) for _ in range(n + 1)]
    for h0 in range(n + 1):
        dp[0][h0] = 0
    for j in range(n):
        ndp = [[NEG] * (n + 1) for _ in range(n + 1)]
        colj = cp[j]
        nexts = range(n + 1) if j < n - 1 else (0,)
        for cur in range(n + 1):
            # pre[x] = max dp[p][cur] for p <= x
            pre = [NEG] * (n + 1)
            m = NEG
            for p in range(n + 1):
                if dp[p][cur] > m:
                    m = dp[p][cur]
                pre[p] = m
            # suf[x] = max over p >= x of dp[p][cur] + gain(p)
            suf = [NEG] * (n + 2)
            m = NEG
            for p in range(n, -1, -1):
                v = dp[p][cur] + (colj[p] - colj[cur] if p > cur else 0)
                if v > m:
                    m = v
                suf[p] = m
            for nx in nexts:
                a = pre[nx] + (colj[nx] - colj[cur] if nx > cur else 0)
                b = suf[nx + 1]
                ndp[cur][nx] = a if a > b else b
        dp = ndp
    ans = NEG
    for a in range(n + 1):
        for b in range(n + 1):
            if dp[a][b] > ans:
                ans = dp[a][b]
    return ans
